import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // 1. Assume the new owner is not the zero address (admissible domain)
        vm.assume(_newOwner != address(0));
        // 2. The deployer/test contract is already the owner. Call setOwner as owner.
        c.setOwner(_newOwner);
        // 3. Assert that the actual owner is now the new owner.
