pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. admissible domain: caller != address(0) to avoid empty calls; newOwner != caller to force a change
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Record previous owner
        address prevOwner = c.owner();

        // 2. drive: impersonate caller and attempt setOwner(newOwner)
        vm.prank(caller);
        bool success;
        try c.setOwner(newOwner) returns (bool ok) {
            success = ok;
        } catch {
            success = false;
        }

        // 3. Assertion: if the caller was the owner, the call must succeed (true + owner updated);
        //    otherwise the call must revert (false). The reference holds this for all inputs;
        //    the bug allows non-owner calls to succeed, breaking the rule.
        assertTrue(success == (caller == prevOwner));
    }
}

