pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The original owner is the deployer of setUp, i.e., address(this).
        address originalOwner = c.owner();
        vm.assume(newOwner != originalOwner);

        vm.prank(originalOwner);
        bool success = false;
        try c.setOwner(newOwner) returns (bool returned) {
            // Original contract succeeds and updates owner.
            success = returned;
        } catch {
            success = false;
        }

        // If the call did not revert, we must have a new owner equal to the argument.
        // Original: success is true and owner == newOwner.
        // Mutant: never reaches the try block body; success stays false, assertion fails.
        assertTrue(!success || c.owner() == newOwner);
    }
}

