pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address originalOwner = c.owner();

        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        if (caller == originalOwner) {
            // If the caller is the owner, the call must succeed and actually change the owner
            assertTrue(success && c.owner() == newOwner);
        } else {
            // If the caller is NOT the owner, the call must fail and the owner must remain unchanged
            assertTrue(!success && c.owner() == originalOwner);
        }
    }
}

